/* Canei Subirats — Catalan column of the translation dictionary (ES → CA).
 *
 * Kept in its own file rather than as a third element inside i18n-dict.js's
 * pairs, for one reason: this is the column most likely to need correcting by
 * somebody who is not editing the application. A native speaker can review
 * and fix this file end to end without ever opening the ES/EN spine, and a
 * diff on it says exactly what changed about the Catalan and nothing else.
 *
 * The key is the SPANISH string, because Spanish is the language the
 * application is written in and therefore the only form every entry is
 * guaranteed to have (see the hub note in i18n.js).
 *
 * Completeness is enforced: tests/i18n/coverage.mjs fails when an entry here
 * is missing, empty or orphaned. Where the Catalan is genuinely identical to
 * the Spanish — which happens often, and more often in short technical
 * labels — it is written out in full rather than omitted, so the file reads
 * as a decision taken rather than a line forgotten.
 */
window.CANEI_DICT = window.CANEI_DICT || {};
