  /* ==========================================================================
     THE BACKLOG, CLEARED — 1.036 entries, 2026-08-17.
     ==========================================================================
     Until now a Catalan reader saw SPANISH wherever an entry was missing: the
     layer falls back to the hub language, so the gap was invisible to everyone
     except the person reading it. These are the strings that had no Catalan
     form, translated in one pass, which is why they sit together rather than
     scattered through the file above.

     THEY ARE MACHINE-AUTHORED. That is stated plainly so the review has a
     scope instead of a rumour: a native speaker checking this file needs to
     read THIS block, not the two thousand entries that precede it. The
     vocabulary used is the building trade's own — enderroc, envà, arrebossat,
     lampisteria, aixetes, paviment, trencadís of register avoided — and the
     formal plural the rest of the product uses when it addresses a customer.

     Where a string is genuinely identical in both languages it is written out
     in full rather than omitted, per the note at the top of this file: a line
     that reads the same in both is a decision somebody took, not a line
     somebody forgot.
     ========================================================================== */
