  "código de cuenta": "codi de compte",
  "Cada cuenta, su estado financiero y la línea en la que se agrupa. Los presupuestos son anuales; el presupuesto del periodo se distribuye uniformemente.":
    "Cada compte, el seu estat financer i la línia en què s'agrupa. Els pressupostos són anuals; el pressupost del període es distribueix uniformement.",
  "Ingresos y gastos reales por mes y cuenta. La cuenta de resultados los suma en el periodo seleccionado.":
    "Ingressos i despeses reals per mes i compte. El compte de resultats els suma en el període seleccionat.",
  "Saldos de cierre a una fecha, por cuenta. El de apertura (2025-12) y el actual (2026-07) alimentan el balance y las variaciones del flujo de caja.":
    "Saldos de tancament a una data, per compte. El d'obertura (2025-12) i l'actual (2026-07) alimenten el balanç i les variacions del flux de caixa.",
  "Facturas de clientes pendientes de cobro con su vencimiento — determina el DSO y la antigüedad de cobros.":
    "Factures de clients pendents de cobrament amb el seu venciment — determina el DSO i l'antiguitat de cobraments.",
  "Facturas de proveedores pendientes de pago con su vencimiento — determina el DPO y la antigüedad de pagos.":
    "Factures de proveïdors pendents de pagament amb el seu venciment — determina el DPO i l'antiguitat de pagaments.",
  "IVA repercutido frente a soportado por periodo (Modelo 303) y retenciones (Modelo 111) — el neto es lo que se liquida.":
    "IVA repercutit enfront de suportat per període (Model 303) i retencions (Model 111) — el net és el que es liquida.",
  "Deuda pendiente con tipo y calendario — alimenta los intereses, la deuda neta y el flujo de caja de financiación.":
    "Deute pendent amb tipus i calendari — alimenta els interessos, el deute net i el flux de caixa de finançament.",
  "Saldos en vivo por cuenta — juntos forman la línea de caja del balance.":
    "Saldos en viu per compte — junts formen la línia de caixa del balanç.",
  "Datos no contables usados por los KPI — plantilla, cartera de pedidos y pipeline abierto.":
    "Dades no comptables utilitzades pels KPI — plantilla, cartera de comandes i pipeline obert.",
  "Cada cuenta, su estado financiero y la línea en la que se agrupa. Los presupuestos son anuales; el presupuesto del periodo se distribuye uniformemente. Editar cualquier cifra recalcula al instante todos los estados y KPI.":
    "Cada compte, el seu estat financer i la línia en què s'agrupa. Els pressupostos són anuals; el pressupost del període es distribueix uniformement. Editar qualsevol xifra recalcula a l'instant tots els estats i KPI.",
  "Ingresos y gastos reales por mes y cuenta. La cuenta de resultados los suma en el periodo seleccionado. Editar cualquier cifra recalcula al instante todos los estados y KPI.":
    "Ingressos i despeses reals per mes i compte. El compte de resultats els suma en el període seleccionat. Editar qualsevol xifra recalcula a l'instant tots els estats i KPI.",
  "Saldos de cierre a una fecha, por cuenta. El de apertura (2025-12) y el actual (2026-07) alimentan el balance y las variaciones del flujo de caja. Editar cualquier cifra recalcula al instante todos los estados y KPI.":
    "Saldos de tancament a una data, per compte. El d'obertura (2025-12) i l'actual (2026-07) alimenten el balanç i les variacions del flux de caixa. Editar qualsevol xifra recalcula a l'instant tots els estats i KPI.",
  "Facturas de clientes pendientes de cobro con su vencimiento — determina el DSO y la antigüedad de cobros. Editar cualquier cifra recalcula al instante todos los estados y KPI.":
    "Factures de clients pendents de cobrament amb el seu venciment — determina el DSO i l'antiguitat de cobraments. Editar qualsevol xifra recalcula a l'instant tots els estats i KPI.",
  "Facturas de proveedores pendientes de pago con su vencimiento — determina el DPO y la antigüedad de pagos. Editar cualquier cifra recalcula al instante todos los estados y KPI.":
    "Factures de proveïdors pendents de pagament amb el seu venciment — determina el DPO i l'antiguitat de pagaments. Editar qualsevol xifra recalcula a l'instant tots els estats i KPI.",
  "IVA repercutido frente a soportado por periodo (Modelo 303) y retenciones (Modelo 111) — el neto es lo que se liquida. Editar cualquier cifra recalcula al instante todos los estados y KPI.":
    "IVA repercutit enfront de suportat per període (Model 303) i retencions (Model 111) — el net és el que es liquida. Editar qualsevol xifra recalcula a l'instant tots els estats i KPI.",
  "Deuda pendiente con tipo y calendario — alimenta los intereses, la deuda neta y el flujo de caja de financiación. Editar cualquier cifra recalcula al instante todos los estados y KPI.":
    "Deute pendent amb tipus i calendari — alimenta els interessos, el deute net i el flux de caixa de finançament. Editar qualsevol xifra recalcula a l'instant tots els estats i KPI.",
  "Saldos en vivo por cuenta — juntos forman la línea de caja del balance. Editar cualquier cifra recalcula al instante todos los estados y KPI.":
    "Saldos en viu per compte — junts formen la línia de caixa del balanç. Editar qualsevol xifra recalcula a l'instant tots els estats i KPI.",
  "Datos no contables usados por los KPI — plantilla, cartera de pedidos y pipeline abierto. Editar cualquier cifra recalcula al instante todos los estados y KPI.":
    "Dades no comptables utilitzades pels KPI — plantilla, cartera de comandes i pipeline obert. Editar qualsevol xifra recalcula a l'instant tots els estats i KPI.",
