    "Fotos, documents, els PDF de pressupost i factura i cada correu s'arxiven per pas — desats en aquest dispositiu.",
  "Registro de actividad": "Registre d'activitat",
  "Listo — introduzca su proyecto para comenzar.":
    "A punt — introduïu el vostre projecte per començar.",
  "Qué demuestra esto": "Què demostra això",
  "Sus datos, un único hilo limpio: captación → beneficio → reseña.":
    "Les vostres dades, un únic fil net: captació → benefici → ressenya.",
  "Introduzca el proyecto una vez; el libro, los PDF de presupuesto y factura y cada correo al cliente se generan automáticamente con la identidad corporativa completa. Las fotos y los documentos se archivan por paso en una carpeta de proyecto descargable. Los correos se redactan para su revisión — nada se envía sin usted.":
    "Introduïu el projecte una vegada; el llibre, els PDF de pressupost i factura i cada correu al client es generen automàticament amb la identitat corporativa completa. Les fotos i els documents s'arxiven per pas en una carpeta de projecte descarregable. Els correus es redacten perquè els reviseu — no s'envia res sense vosaltres.",
