  /* «falta» is Spanish; Catalan wants «en falta / en falten».
     This rule used to map the string to ITSELF — `"$1% · falta $2"` — which
     made it untranslatable in the worst possible way: a rule that matches has
     handled the string, so the layer reported success and the miss ledger
     never recorded it. The only thing that found it was the rendered-page
     audit, comparing the Spanish and Catalan renders and seeing them
     identical. An identity rule is not a decision that two languages agree; it
     is a gap wearing the costume of one.
     Two rules because the verb agrees with the count, and the singular is not
     a rounding error on a completeness pill somebody reads every day. The
     percentage accepts a decimal — `12,5% · falta 3` is a real value. */
